  ["Chapter VII"] = "Kapitel VII",
  ["Chapter VIII"] = "Kapitel VIII",
  ["Clearly stolen."] = "Tydeligvis stjålet.",
  ["Closely guarded shamanistic secrets of the Grimtotem clan. A fine addition to any library's collection."] = "Tæt bevogtede shamanistiske hemmeligheder fra Grimtotem-klanen. En fin tilføjelse til enhver bibliotekssamling.",
  ["Commonly used by crusaders to ward off bad luck. Conveniently, it also useful for cooking."] = "Bruges ofte af korsfarere til at afværge uheld. Praktisk nok er den også nyttig til madlavning.",
  ["Completely inert and inactive."] = "Fuldstændig inert og inaktiv.",
  ["Completely worthless."] = "Fuldstændig værdiløs.",
  ["Consume immediately! Evaporates faster than you can uncork a flask."] = "Indtag straks! Fordamper hurtigere, end du kan proppe en kolbe op.",
  ["Consumed, never to return."] = "Fortæret, aldrig at vende tilbage.",
